"use client"

// OnboardingStepper: one token-driven multi-step flow with nine progress
// shapes, compatible label modes, reached-step navigation, and focus handoff.
// The stamp script publishes this source unchanged to every design system.

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import type { KeyboardEvent } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { Button } from "./button"
import { OnboardingStepNavigation } from "./ix-onboarding-stepper-navigation"
import { OnboardingProgressIndicator } from "./ix-onboarding-stepper-progress"
import {
  DEFAULT_ONBOARDING_MOTION,
  clampOnboardingIndex,
  getOnboardingTransition,
} from "./ix-onboarding-stepper-types"
import type {
  OnboardingDirection,
  OnboardingStepperProps,
} from "./ix-onboarding-stepper-types"

export { DEFAULT_ONBOARDING_MOTION, resolveOnboardingLabelMode } from "./ix-onboarding-stepper-types"
export type {
  OnboardingDirection,
  OnboardingLabelMode,
  OnboardingMotion,
  OnboardingProgressStyle,
  OnboardingStepperProps,
  OnboardingStepperStep,
} from "./ix-onboarding-stepper-types"

/** Renders a reusable onboarding flow using the active design-system tokens. */
export function OnboardingStepper({
  steps,
  index,
  defaultIndex = 0,
  onIndexChange,
  complete,
  completion,
  onComplete,
  onSkip,
  progressStyle = "segments",
  labelMode = "all",
  motionConfig,
  progressLabel = "Onboarding progress",
  backLabel = "Previous step",
  nextLabel = "Next step",
  finishLabel = "Finish",
  skipLabel = "Skip for now",
  className = "",
}: OnboardingStepperProps) {
  const [internalIndex, setInternalIndex] = useState(() =>
    clampOnboardingIndex(defaultIndex, steps.length),
  )
  const [internalComplete, setInternalComplete] = useState(false)
  const current = clampOnboardingIndex(index ?? internalIndex, steps.length)
  const [progress, setProgress] = useState<{
    direction: OnboardingDirection
    furthest: number
    index: number
  }>(() => ({
    direction: 1,
    furthest: current,
    index: current,
  }))
  if (progress.index !== current) {
    setProgress({
      direction: current > progress.index ? 1 : -1,
      furthest: Math.max(progress.furthest, current),
      index: current,
    })
  }
  const { direction, furthest } = progress
  const listRef = useRef<HTMLOListElement>(null)
  const panelNode = useRef<HTMLDivElement | null>(null)
  // The next panel mounts only after the last one has left, so the step change
  // asks for focus and the new panel takes it as it mounts.
  const panelFocusPending = useRef(false)
  const completionRef = useRef<HTMLDivElement>(null)
  const completionRequested = useRef(false)
  const intent = useRef<"list" | "panel" | null>(null)
  const controlled = index !== undefined
  const isComplete = complete ?? internalComplete
  const reduced = useReducedMotion() === true
  const config = { ...DEFAULT_ONBOARDING_MOTION, ...motionConfig }
  const transition = getOnboardingTransition(reduced, config)
  const step = steps[current]

  useEffect(() => {
    const move = intent.current
    intent.current = null
    if (move === "list") {
      listRef.current?.querySelector<HTMLButtonElement>('button[data-current="true"]')?.focus()
    } else if (move === "panel") {
      const panel = panelNode.current
      if (panel?.dataset.step === steps[current]?.id) panel.focus({ preventScroll: true })
      else panelFocusPending.current = true
    }
  }, [current, steps])

  const panelRef = useCallback((node: HTMLDivElement | null) => {
    panelNode.current = node
    if (node && panelFocusPending.current) {
      panelFocusPending.current = false
      node.focus({ preventScroll: true })
    }
  }, [])

  useEffect(() => {
    if (!isComplete || !completionRequested.current) return
    completionRequested.current = false
    completionRef.current?.focus({ preventScroll: true })
  }, [isComplete])

  const goTo = useCallback(
    (target: number, nextIntent: "list" | "panel") => {
      const next = clampOnboardingIndex(target, steps.length)
      if (next === current) return
      const nextDirection: OnboardingDirection = next > current ? 1 : -1
      intent.current = nextIntent
      if (!controlled) setInternalIndex(next)
      onIndexChange?.(next, nextDirection)
    },
    [controlled, current, onIndexChange, steps.length],
  )

  const moveNext = () => {
    if (current < steps.length - 1) {
      goTo(current + 1, "panel")
      return
    }
    completionRequested.current = true
    if (complete === undefined) setInternalComplete(true)
    onComplete?.()
  }

  const onStepKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    let target = current
    if (event.key === "ArrowRight" || event.key === "ArrowDown") target = current + 1
    else if (event.key === "ArrowLeft" || event.key === "ArrowUp") target = current - 1
    else if (event.key === "Home") target = 0
    else if (event.key === "End") target = furthest
    else return
    event.preventDefault()
    goTo(Math.min(clampOnboardingIndex(target, steps.length), furthest), "list")
  }

  const variants = useMemo(
    () => ({
      enter: (value: OnboardingDirection) =>
        reduced ? { opacity: 1 } : { opacity: 0, x: value * config.offset },
      center: { opacity: 1, x: 0 },
      exit: (value: OnboardingDirection) =>
        reduced
          ? { opacity: 1 }
          : {
              opacity: 0,
              x: value * -config.offset,
              transition: { duration: config.exitDuration, ease: "easeIn" as const },
            },
    }),
    [config.exitDuration, config.offset, reduced],
  )

  if (!step) return null

  return (
    <section className={`w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm ${className}`}>
      <p aria-live="polite" className="sr-only">
        {isComplete ? "Onboarding complete" : `Step ${current + 1} of ${steps.length}: ${step.title}`}
      </p>

      {isComplete ? (
        <div
          ref={completionRef}
          tabIndex={-1}
          role="group"
          aria-label="Onboarding complete"
          className="p-8 text-center outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
        >
          {completion ?? (
            <>
              <h2 className="text-lg font-semibold text-foreground">Onboarding complete</h2>
              <p className="mt-2 text-sm text-muted-foreground">Your choices are ready to use.</p>
            </>
          )}
        </div>
      ) : (
        <>
          <div className="border-b border-border p-5">
            <OnboardingStepNavigation
              steps={steps}
              index={current}
              furthest={furthest}
              label={progressLabel}
              listRef={listRef}
              onKeyDown={onStepKeyDown}
              onSelect={(target) => goTo(target, "list")}
            />
            <OnboardingProgressIndicator
              style={progressStyle}
              steps={steps}
              index={current}
              labelMode={labelMode}
              transition={transition}
            />
          </div>

          <div className="p-5">
            <AnimatePresence initial={false} mode="wait" custom={direction}>
              <motion.div
                ref={panelRef}
                key={step.id}
                data-step={step.id}
                tabIndex={-1}
                role="group"
                aria-label={step.title}
                custom={direction}
                variants={variants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={transition}
                className="outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <h2 className="text-lg font-semibold tracking-tight text-foreground">{step.title}</h2>
                {step.description ? (
                  <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{step.description}</p>
                ) : null}
                {step.content ? <div className="mt-5">{step.content}</div> : null}
              </motion.div>
            </AnimatePresence>
          </div>

          <div className="flex items-center gap-3 border-t border-border p-4">
            {onSkip ? (
              <Button
                type="button"
                onClick={onSkip}
                className="min-h-11 bg-transparent px-3 text-sm font-medium text-muted-foreground shadow-none hover:bg-muted/50 hover:text-foreground"
              >
                {skipLabel}
              </Button>
            ) : null}
            {current > 0 ? (
              <Button
                type="button"
                onClick={() => goTo(current - 1, "panel")}
                className="min-h-11 border border-border bg-background px-4 text-sm font-medium text-foreground shadow-none hover:bg-muted"
              >
                {backLabel}
              </Button>
            ) : null}
            <Button
              type="button"
              disabled={step.complete === false}
              onClick={moveNext}
              className="ml-auto min-h-11 bg-primary px-4 text-sm font-medium text-primary-foreground"
            >
              {current === steps.length - 1 ? finishLabel : nextLabel}
            </Button>
          </div>
        </>
      )}
    </section>
  )
}

import { motion } from "motion/react"

import { OnboardingStepLabels } from "./ix-onboarding-stepper-labels"
import { getOnboardingStepState } from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders compact dots whose current step morphs into a short bar. */
export function OnboardingDotsIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  return (
    <>
      <div data-progress-style="dots" className="flex h-8 items-center justify-center gap-1">
        {steps.map((step, stepIndex) => {
          const state = getOnboardingStepState(stepIndex, index)
          return (
            <motion.span
              key={step.id}
              data-progress-step={stepIndex}
              data-step-state={state}
              layout="size"
              transition={transition}
              className={`block h-2 rounded-full ${
                state === "current"
                  ? "w-6 bg-primary"
                  : state === "completed"
                    ? "w-2 bg-primary"
                    : "w-2 bg-muted"
              }`}
            />
          )
        })}
      </div>
      <OnboardingStepLabels steps={steps} index={index} mode={labelMode} />
    </>
  )
}

import { motion } from "motion/react"

import { OnboardingStepLabels } from "./ix-onboarding-stepper-labels"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders a numeric fraction with a continuous progress bar. */
export function OnboardingFractionIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  const progress = (index + 1) / steps.length

  return (
    <div data-progress-style="fraction" className="grid gap-3 py-2">
      <div className="flex items-baseline justify-between tabular-nums">
        <span className="text-2xl font-semibold text-foreground">
          {String(index + 1).padStart(2, "0")}
        </span>
        <span className="text-xs text-muted-foreground">
          of {String(steps.length).padStart(2, "0")}
        </span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-muted">
        <motion.span
          initial={false}
          animate={{ scaleX: progress }}
          transition={transition}
          className="block h-full origin-left rounded-full bg-primary"
        />
      </div>
      <OnboardingStepLabels steps={steps} index={index} mode={labelMode} />
    </div>
  )
}

import {
  getOnboardingLabelTone,
  getOnboardingStepState,
  isOnboardingLabelVisible,
} from "./ix-onboarding-stepper-types"
import type {
  OnboardingLabelMode,
  OnboardingStepperStep,
} from "./ix-onboarding-stepper-types"

/** Renders labels beneath a horizontal progress indicator. */
export function OnboardingStepLabels({
  steps,
  index,
  mode,
}: {
  steps: OnboardingStepperStep[]
  index: number
  mode: OnboardingLabelMode
}) {
  if (mode === "none") return null

  if (mode === "current") {
    return (
      <p className="mt-2 text-center text-sm font-semibold text-primary">
        {steps[index]?.label}
      </p>
    )
  }

  return (
    <ol
      className="mt-2 grid list-none gap-2 p-0"
      style={{ gridTemplateColumns: `repeat(${steps.length}, minmax(0, 1fr))` }}
    >
      {steps.map((step, stepIndex) => {
        const current = stepIndex === index
        const state = getOnboardingStepState(stepIndex, index)
        if (!isOnboardingLabelVisible(mode, current)) return null

        return (
          <li
            key={step.id}
            data-step-state={state}
            className={`min-w-0 text-center text-xs ${getOnboardingLabelTone(state)}`}
          >
            <span className="block truncate">{step.label}</span>
          </li>
        )
      })}
    </ol>
  )
}

import type { KeyboardEvent, RefObject } from "react"

import { Button } from "./button"
import type { OnboardingStepperStep } from "./ix-onboarding-stepper-types"

/** Exposes reached-step navigation without crowding the visual indicator. */
export function OnboardingStepNavigation({
  steps,
  index,
  furthest,
  label,
  onSelect,
  onKeyDown,
  listRef,
}: {
  steps: OnboardingStepperStep[]
  index: number
  furthest: number
  label: string
  onSelect: (index: number) => void
  onKeyDown: (event: KeyboardEvent<HTMLElement>) => void
  listRef: RefObject<HTMLOListElement | null>
}) {
  return (
    <nav
      aria-label={label}
      className="sr-only focus-within:not-sr-only focus-within:mb-3 focus-within:block focus-within:rounded-lg focus-within:border focus-within:border-border focus-within:bg-background focus-within:p-2"
    >
      <ol ref={listRef} className="flex list-none flex-wrap gap-2 p-0">
        {steps.map((step, stepIndex) => (
          <li key={step.id}>
            {stepIndex <= furthest ? (
              <Button
                type="button"
                data-current={stepIndex === index ? "true" : undefined}
                tabIndex={stepIndex === index ? 0 : -1}
                aria-current={stepIndex === index ? "step" : undefined}
                aria-label={`Step ${stepIndex + 1} of ${steps.length}: ${step.label}`}
                onClick={() => onSelect(stepIndex)}
                onKeyDown={onKeyDown}
                className="min-h-11 bg-background px-3 text-sm text-foreground shadow-none"
              >
                {step.label}
              </Button>
            ) : (
              <span className="flex min-h-11 items-center px-3 text-sm text-muted-foreground">
                {step.label}
              </span>
            )}
          </li>
        ))}
      </ol>
    </nav>
  )
}

import { motion } from "motion/react"

import { OnboardingStepLabels } from "./ix-onboarding-stepper-labels"
import { getOnboardingStepState } from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders numbered circles for each onboarding step. */
export function OnboardingNumbersIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  return (
    <>
      <div data-progress-style="numbers" className="flex h-12 items-center gap-2">
        {steps.map((step, stepIndex) => {
          const state = getOnboardingStepState(stepIndex, index)
          return (
            <span key={step.id} className="grid flex-1 place-items-center">
              <motion.span
                data-step-state={state}
                animate={{ scale: state === "current" ? 1.08 : 1 }}
                transition={transition}
                className={`grid size-8 place-items-center rounded-full text-xs font-semibold tabular-nums ${
                  state === "upcoming"
                    ? "bg-muted text-muted-foreground"
                    : state === "current"
                      ? "bg-primary text-primary-foreground ring-4 ring-primary/15"
                      : "bg-primary text-primary-foreground"
                }`}
              >
                {stepIndex + 1}
              </motion.span>
            </span>
          )
        })}
      </div>
      <OnboardingStepLabels steps={steps} index={index} mode={labelMode} />
    </>
  )
}

import { motion } from "motion/react"

import { OnboardingStepLabels } from "./ix-onboarding-stepper-labels"
import { getOnboardingStepState } from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

const LEVEL_PATH_HEIGHTS = [62, 24, 58, 18, 52]
const LEVEL_PATH_VIEWBOX_HEIGHT = 80

/** Renders a stable level path whose active stroke reveals from left to right. */
export function OnboardingPathIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  const points = steps.map((_, stepIndex) => ({
    x: steps.length > 1 ? 6 + (stepIndex * 88) / (steps.length - 1) : 50,
    y: LEVEL_PATH_HEIGHTS[stepIndex] ?? 50,
  }))
  const pointList = points.map(({ x, y }) => `${x},${y}`).join(" ")
  const progressEdge = points[index]?.x ?? 0

  return (
    <div data-progress-style="path">
      <div className="relative h-20">
        <svg viewBox="0 0 100 80" preserveAspectRatio="none" className="absolute inset-0 size-full">
          <polyline
            points={pointList}
            fill="none"
            vectorEffect="non-scaling-stroke"
            className="stroke-border"
            strokeWidth="2"
          />
        </svg>
        <motion.svg
          data-level-path-progress
          data-progress-edge={progressEdge}
          data-progress-clip={`inset(0 ${100 - progressEdge}% 0 0)`}
          viewBox="0 0 100 80"
          preserveAspectRatio="none"
          className="absolute inset-0 size-full"
          initial={false}
          animate={{ clipPath: `inset(0 ${100 - progressEdge}% 0 0)` }}
          transition={transition}
        >
          <polyline
            points={pointList}
            fill="none"
            vectorEffect="non-scaling-stroke"
            className="stroke-primary"
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </motion.svg>
        <ol className="absolute inset-0 list-none p-0">
          {steps.map((step, stepIndex) => {
            const state = getOnboardingStepState(stepIndex, index)
            const point = points[stepIndex]
            return (
              <li
                key={step.id}
                data-step-state={state}
                className="absolute -translate-x-1/2 -translate-y-1/2"
                style={{
                  left: `${point?.x ?? 50}%`,
                  top: `${((point?.y ?? 50) / LEVEL_PATH_VIEWBOX_HEIGHT) * 100}%`,
                }}
              >
                <motion.span
                  animate={{ scale: state === "current" ? 1.12 : 1 }}
                  transition={transition}
                  className={`grid size-9 place-items-center rounded-full border-4 border-card text-xs font-semibold tabular-nums ${
                    state === "upcoming"
                      ? "bg-muted text-muted-foreground"
                      : state === "current"
                        ? "bg-primary text-primary-foreground ring-4 ring-primary/15"
                        : "bg-primary text-primary-foreground"
                  }`}
                >
                  {stepIndex + 1}
                </motion.span>
              </li>
            )
          })}
        </ol>
      </div>
      <OnboardingStepLabels steps={steps} index={index} mode={labelMode} />
    </div>
  )
}

import { OnboardingCircleIndicator } from "./ix-onboarding-stepper-circle"
import { OnboardingDotsIndicator } from "./ix-onboarding-stepper-dots"
import { OnboardingFractionIndicator } from "./ix-onboarding-stepper-fraction"
import { OnboardingNumbersIndicator } from "./ix-onboarding-stepper-numbers"
import { OnboardingPathIndicator } from "./ix-onboarding-stepper-path"
import { OnboardingRailIndicator } from "./ix-onboarding-stepper-rail"
import { OnboardingSegmentsIndicator } from "./ix-onboarding-stepper-segments"
import { OnboardingUnderlineIndicator } from "./ix-onboarding-stepper-underline"
import { OnboardingVerticalIndicator } from "./ix-onboarding-stepper-vertical"
import { resolveOnboardingLabelMode } from "./ix-onboarding-stepper-types"
import type {
  OnboardingIndicatorProps,
  OnboardingProgressStyle,
} from "./ix-onboarding-stepper-types"

/** Selects one of the supported progress shapes for an onboarding flow. */
export function OnboardingProgressIndicator({
  style,
  ...props
}: OnboardingIndicatorProps & { style: OnboardingProgressStyle }) {
  const labels = resolveOnboardingLabelMode(style, props.labelMode)
  const indicatorProps = { ...props, labelMode: labels }

  return (
    <div data-testid="onboarding-progress" data-label-mode={labels}>
      <p className="mb-2 text-xs font-medium tabular-nums text-muted-foreground">
        Step {props.index + 1} of {props.steps.length}
      </p>
      <div aria-hidden="true">
        {style === "dots" ? <OnboardingDotsIndicator {...indicatorProps} /> : null}
        {style === "segments" ? <OnboardingSegmentsIndicator {...indicatorProps} /> : null}
        {style === "numbers" ? <OnboardingNumbersIndicator {...indicatorProps} /> : null}
        {style === "rail" ? <OnboardingRailIndicator {...indicatorProps} /> : null}
        {style === "path" ? <OnboardingPathIndicator {...indicatorProps} /> : null}
        {style === "fraction" ? <OnboardingFractionIndicator {...indicatorProps} /> : null}
        {style === "circle" ? <OnboardingCircleIndicator {...indicatorProps} /> : null}
        {style === "vertical" ? <OnboardingVerticalIndicator {...indicatorProps} /> : null}
        {style === "underline" ? <OnboardingUnderlineIndicator {...indicatorProps} /> : null}
      </div>
    </div>
  )
}

import { motion } from "motion/react"

import { OnboardingStepLabels } from "./ix-onboarding-stepper-labels"
import { getOnboardingStepState } from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders a connected horizontal rail with nodes for every step. */
export function OnboardingRailIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  const progress = steps.length > 1 ? index / (steps.length - 1) : 1

  return (
    <>
      <div data-progress-style="rail" className="relative flex h-12 items-center justify-between px-2">
        <span className="absolute inset-x-2 top-1/2 h-1 -translate-y-1/2 overflow-hidden rounded-full bg-muted">
          <motion.span
            initial={false}
            animate={{ scaleX: progress }}
            transition={transition}
            className="block h-full origin-left rounded-full bg-primary"
          />
        </span>
        {steps.map((step, stepIndex) => {
          const state = getOnboardingStepState(stepIndex, index)
          return (
            <span
              key={step.id}
              data-step-state={state}
              className={`relative z-10 rounded-full border-2 border-card ${
                state === "current"
                  ? "size-4 bg-primary ring-4 ring-primary/15"
                  : state === "completed"
                    ? "size-3 bg-primary"
                    : "size-3 bg-muted"
              }`}
            />
          )
        })}
      </div>
      <OnboardingStepLabels steps={steps} index={index} mode={labelMode} />
    </>
  )
}

import { motion } from "motion/react"

import { OnboardingStepLabels } from "./ix-onboarding-stepper-labels"
import { getOnboardingStepState } from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders a segmented bar with distinct completed, current, and upcoming states. */
export function OnboardingSegmentsIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  return (
    <>
      <div data-progress-style="segments" className="flex h-8 items-center gap-1.5">
        {steps.map((step, stepIndex) => {
          const state = getOnboardingStepState(stepIndex, index)
          return (
            <span
              key={step.id}
              data-step-state={state}
              className={`h-2 flex-1 overflow-hidden rounded-full ${
                state === "current"
                  ? "bg-muted ring-2 ring-primary/20 ring-offset-2 ring-offset-card"
                  : "bg-muted"
              }`}
            >
              <motion.span
                initial={false}
                animate={{ scaleX: state === "upcoming" ? 0 : 1 }}
                transition={transition}
                className={`block h-full origin-left rounded-full ${
                  state === "completed" ? "bg-primary/65" : "bg-primary"
                }`}
              />
            </span>
          )
        })}
      </div>
      <OnboardingStepLabels steps={steps} index={index} mode={labelMode} />
    </>
  )
}

import type { ReactNode } from "react"

/** The progress shapes supported by the onboarding stepper. */
export type OnboardingProgressStyle =
  | "dots"
  | "segments"
  | "numbers"
  | "rail"
  | "path"
  | "fraction"
  | "circle"
  | "vertical"
  | "underline"

/** Controls how much step copy appears beside the progress shape. */
export type OnboardingLabelMode = "none" | "current" | "all"

/** Motion values shared by the progress indicator and panel transition. */
export type OnboardingMotion = {
  offset: number
  stiffness: number
  damping: number
  mass: number
  exitDuration: number
}

/** One step in an onboarding, setup, survey, or product-tour flow. */
export type OnboardingStepperStep = {
  id: string
  label: string
  title: string
  description?: string
  content?: ReactNode
  complete?: boolean
}

/** Direction reported when the current step changes. */
export type OnboardingDirection = 1 | -1

/** Props for the shared onboarding stepper. */
export type OnboardingStepperProps = {
  steps: OnboardingStepperStep[]
  index?: number
  defaultIndex?: number
  onIndexChange?: (index: number, direction: OnboardingDirection) => void
  complete?: boolean
  completion?: ReactNode
  onComplete?: () => void
  onSkip?: () => void
  progressStyle?: OnboardingProgressStyle
  labelMode?: OnboardingLabelMode
  motionConfig?: Partial<OnboardingMotion>
  progressLabel?: string
  backLabel?: string
  nextLabel?: string
  finishLabel?: string
  skipLabel?: string
  className?: string
}

/** Default motion values for onboarding panels and indicators. */
export const DEFAULT_ONBOARDING_MOTION: OnboardingMotion = {
  offset: 18,
  stiffness: 280,
  damping: 30,
  mass: 0.8,
  exitDuration: 0.12,
}

/** Visual state for one step in the progress indicator. */
export type OnboardingStepState = "completed" | "current" | "upcoming"

/** Keeps a requested step inside the available range. */
export function clampOnboardingIndex(value: number, total: number) {
  if (total < 1) return 0
  return Math.max(0, Math.min(total - 1, Math.trunc(value)))
}

/** Returns the visual state of one step relative to the current step. */
export function getOnboardingStepState(
  stepIndex: number,
  currentIndex: number,
): OnboardingStepState {
  if (stepIndex < currentIndex) return "completed"
  if (stepIndex === currentIndex) return "current"
  return "upcoming"
}

/** Resolves label choices that do not fit a progress shape. */
export function resolveOnboardingLabelMode(
  style: OnboardingProgressStyle,
  mode: OnboardingLabelMode,
): OnboardingLabelMode {
  if (style === "vertical") return "all"
  if ((style === "circle" || style === "dots") && mode === "all") return "current"
  return mode
}

/** Reports whether one label belongs in the selected label mode. */
export function isOnboardingLabelVisible(
  mode: OnboardingLabelMode,
  current: boolean,
) {
  return mode === "all" || (mode === "current" && current)
}

/** Returns semantic text classes for completed, current, and upcoming steps. */
export function getOnboardingLabelTone(state: OnboardingStepState) {
  if (state === "current") return "font-semibold text-primary"
  if (state === "completed") return "font-medium text-foreground"
  return "text-muted-foreground"
}

/** Returns the shared Motion transition, including the reduced-motion form. */
export function getOnboardingTransition(
  reduced: boolean,
  config: OnboardingMotion,
) {
  return reduced
    ? { duration: 0 }
    : {
        type: "spring" as const,
        stiffness: config.stiffness,
        damping: config.damping,
        mass: config.mass,
      }
}

/** Props shared by every visual progress indicator. */
export type OnboardingIndicatorProps = {
  steps: OnboardingStepperStep[]
  index: number
  labelMode: OnboardingLabelMode
  transition: ReturnType<typeof getOnboardingTransition>
}

import { useId } from "react"
import { motion } from "motion/react"

import {
  getOnboardingLabelTone,
  getOnboardingStepState,
} from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders an underline that moves only within its own stepper instance. */
export function OnboardingUnderlineIndicator({
  steps,
  index,
  labelMode,
  transition,
}: OnboardingIndicatorProps) {
  const activeUnderlineId = useId()

  return (
    <div data-progress-style="underline" className="flex min-h-10 items-end justify-between gap-2">
      {steps.map((step, stepIndex) => {
        const current = stepIndex === index
        const state = getOnboardingStepState(stepIndex, index)
        const text = labelMode === "all" || (labelMode === "current" && current)
          ? step.label
          : stepIndex + 1
        return (
          <span
            key={step.id}
            data-step-state={state}
            className={`relative min-w-6 pb-2 text-center text-xs ${getOnboardingLabelTone(state)}`}
          >
            {text}
            {current ? (
              <motion.span
                layoutId={`${activeUnderlineId}-active`}
                transition={transition}
                className="absolute inset-x-0 bottom-0 h-0.5 rounded-full bg-primary"
              />
            ) : null}
          </span>
        )
      })}
    </div>
  )
}

import { motion } from "motion/react"

import {
  getOnboardingLabelTone,
  getOnboardingStepState,
} from "./ix-onboarding-stepper-types"
import type { OnboardingIndicatorProps } from "./ix-onboarding-stepper-types"

/** Renders a vertical trail with all step labels and a connected active line. */
export function OnboardingVerticalIndicator({
  steps,
  index,
  transition,
}: OnboardingIndicatorProps) {
  const progress = steps.length > 1 ? index / (steps.length - 1) : 1

  return (
    <div data-progress-style="vertical" className="relative">
      <span className="absolute bottom-3 left-1 top-3 w-px -translate-x-1/2 bg-border" />
      <motion.span
        initial={false}
        animate={{ scaleY: progress }}
        transition={transition}
        className="absolute bottom-3 left-1 top-3 w-px origin-top -translate-x-1/2 bg-primary"
      />
      <ol className="relative grid min-h-28 list-none gap-2 py-1">
        {steps.map((step, stepIndex) => {
          const state = getOnboardingStepState(stepIndex, index)
          return (
            <li
              key={step.id}
              data-step-state={state}
              className="relative flex min-h-5 items-center gap-3 text-xs"
            >
              <span
                className={`relative z-10 rounded-full ring-card ${
                  state === "completed"
                    ? "size-2 bg-primary ring-2"
                    : state === "current"
                      ? "size-3 border-2 border-primary bg-card ring-2"
                      : "size-2 border border-muted-foreground/50 bg-muted ring-2"
                }`}
              />
              <span className={getOnboardingLabelTone(state)}>{step.label}</span>
            </li>
          )
        })}
      </ol>
    </div>
  )
}
